 public sealed class TerrainDomainLimits {public int InputVertices=4096,InitialTriangles=8192,ProtectedKnots=8192,IndexReferences=4000000,Work=8000000;}
 public static class ManagedTerrainDomainLocal {
  public const long Scale=1L<<18;
  readonly struct P:IEquatable<P>{public readonly long X,Z;public P(long x,long z){X=x;Z=z;}public bool Equals(P p)=>X==p.X&&Z==p.Z;public override bool Equals(object o)=>o is P p&&Equals(p);public override int GetHashCode()=>unchecked(X.GetHashCode()*397^Z.GetHashCode());}
  static BigInteger Cross(P a,P b,P c)=>(BigInteger)(b.X-a.X)*(c.Z-a.Z)-(BigInteger)(b.Z-a.Z)*(c.X-a.X);
  static long Q(double x){if(!TerrainFieldLimits.Finite(x)||Math.Abs(x)>20000)throw new ArgumentException("Domain coordinate budget; use sourceworldlocal coordinates");return checked((long)Math.Round(x*Scale,MidpointRounding.ToEven));}
