  public static LocalTerrainDomainInput Build(int cellX,int cellZ,IReadOnlyList<IReadOnlyList<TerrainPoint>> footprints,IReadOnlyList<TerrainPoint> sourceHeightKnots,IReadOnlyList<LocalTerrainSeam> seams,TerrainDem dem,Func<double,double,TerrainMeshSample> query,TerrainDomainLimits limits=null,CancellationToken token=default,IReadOnlyList<TerrainPoint> exposedGroundKnots=null){
   var l=limits??new TerrainDomainLimits();if(footprints==null||sourceHeightKnots==null||seams==null||dem==null||query==null||l.InputVertices<4||l.InitialTriangles<2||l.ProtectedKnots<4||l.Work<1||sourceHeightKnots.Count>l.ProtectedKnots)throw new TerrainBudgetException("Domain input budget");long x0=Q(checked(cellX*32)),x1=Q(checked((cellX+1)*32)),z0=Q(checked(cellZ*32)),z1=Q(checked((cellZ+1)*32));int work=0;void Check(){if(++work>l.Work)throw new TerrainBudgetException("Domain workcap");if((work&127)==0)token.ThrowIfCancellationRequested();}
   if(footprints.Count>0&&exposedGroundKnots==null)throw new ArgumentException("Explicit canonical exposed-ground constraints required; packet influenceknots alone are insufficient");if(exposedGroundKnots!=null&&exposedGroundKnots.Count>l.ProtectedKnots)throw new TerrainBudgetException("Exposedground knotcap");var hardByFloat=new Dictionary<(float,float),float>();double originX=(double)x0/Scale,originZ=(double)z0/Scale;if(exposedGroundKnots!=null)foreach(var p in exposedGroundKnots){if(originX+(double)(float)(p.X-originX)!=p.X||originZ+(double)(float)(p.Z-originZ)!=p.Z||(double)(float)p.Y!=p.Y||!TerrainFieldLimits.Finite(p.Y))throw new ArgumentException("Exposedground knots require canonical actualbinary32XYZ");if(p.X<(double)x0/Scale||p.X>(double)x1/Scale||p.Z<(double)z0/Scale||p.Z>(double)z1/Scale)continue;var key=((float)(p.X-originX),(float)(p.Z-originZ));if(hardByFloat.TryGetValue(key,out float old)&&Math.Abs(old-p.Y)>.0002)throw new ArgumentException("Conflicting exposedground heights");hardByFloat[key]=(float)p.Y;}var source=new Paths64();int total=0;foreach(var ring in footprints){Check();if(ring==null||ring.Count<3||ring.Count>l.InputVertices||total+ring.Count>l.InputVertices)throw new TerrainBudgetException("Source-complete localpolygon cap; no partialunion");total+=ring.Count;var p=new Path64();foreach(var v in ring){if(!TerrainFieldLimits.Finite(v.Y))throw new ArgumentException("Nonfinite sourcefootprint Y");p.Add(new Point64(Q(v.X),Q(v.Z)));}source.Add(p);}
   var sourceUnion=Clipper.Union(source,FillRule.NonZero);if(sourceUnion.Sum(r=>r.Count)>l.InputVertices)throw new TerrainBudgetException("Sourceunion vertexcap");
   bool InsidePavement(P p){bool inside=false;foreach(var path in sourceUnion){Check();var result=Clipper.PointInPolygon(new Point64(p.X,p.Z),path);if(result==PointInPolygonResult.IsOn)return false;if(result==PointInPolygonResult.IsInside)inside=!inside;}return inside;}
   var xs=new SortedSet<long>{x0,x1};var zs=new SortedSet<long>{z0,z1};for(int i=1;i<dem.Nx-1;i++){double x=dem.MinX+i*dem.Width/(dem.Nx-1);long q=Q(x);if(q>x0&&q<x1)xs.Add(q);}for(int i=1;i<dem.Nz-1;i++){double z=dem.MinZ+i*dem.Depth/(dem.Nz-1);long q=Q(z);if(q>z0&&q<z1)zs.Add(q);}if((long)(xs.Count-1)*(zs.Count-1)>256)throw new TerrainBudgetException("DEMsubcell cap");
   var targetContours=new Paths64();bool TargetContains(P p){bool inside=false;foreach(var path in targetContours){Check();var result=Clipper.PointInPolygon(new Point64(p.X,p.Z),path);if(result==PointInPolygonResult.IsOn)return true;if(result==PointInPolygonResult.IsInside)inside=!inside;}return inside;}var protectedPoints=new HashSet<P>();var seamPoints=new Dictionary<(float,float),float>();foreach(var seam in seams)for(int i=0;i<seam.Count;i++){var v=seam[i];if(v.X<(double)x0/Scale||v.X>(double)x1/Scale||v.Z<(double)z0/Scale||v.Z>(double)z1/Scale)throw new ArgumentException("Seam belongs to another cell");var key=((float)(v.X-originX),(float)(v.Z-originZ));if(seamPoints.TryGetValue(key,out float old)&&old!=(float)v.Y)throw new ArgumentException("Conflicting canonical cornerseam Y");seamPoints[key]=(float)v.Y;protectedPoints.Add(new P(Q(v.X),Q(v.Z)));}
   var points=new List<P>();var pointIds=new Dictionary<P,int>();var faces=new Dictionary<long,(int A,int B,int C)>();var density=new Dictionary<long,byte>();var adj=new Dictionary<TerrainMeshEdge,HashSet<long>>();var index=new Dictionary<(int,int),HashSet<TerrainMeshEdge>>();long next=0;int refs=0,calls=0,maxCall=0;
   int Vertex(P p){if(pointIds.TryGetValue(p,out int i))return i;i=points.Count;pointIds.Add(p,i);points.Add(p);return i;}
   void Index(TerrainMeshEdge e){var a=points[e.A];var b=points[e.B];int ax=(int)Math.Floor((double)(Math.Min(a.X,b.X)-x0)/Scale),bx=(int)Math.Floor((double)(Math.Max(a.X,b.X)-x0)/Scale),az=(int)Math.Floor((double)(Math.Min(a.Z,b.Z)-z0)/Scale),bz=(int)Math.Floor((double)(Math.Max(a.Z,b.Z)-z0)/Scale);for(int z=az;z<=bz;z++)for(int x=ax;x<=bx;x++){Check();if(++refs>l.IndexReferences)throw new TerrainBudgetException("Domain edgeindex cap");if(!index.TryGetValue((x,z),out var set))index.Add((x,z),set=new HashSet<TerrainMeshEdge>());set.Add(e);}}
