   void Add(int a,int b,int c,byte region){Check();int sign=Cross(points[a],points[b],points[c]).Sign;if(sign==0)throw new ArgumentException("Zero-area upstreamCDT face; no face deletion workaround");if(sign>0){int k=b;b=c;c=k;}if(faces.Count>=l.InitialTriangles)throw new TerrainBudgetException("Restoredinitialtriangle cap");long id=next++;var t=(a,b,c);faces.Add(id,t);density.Add(id,region);foreach(var e in Edges(t)){if(!adj.TryGetValue(e,out var set)){adj.Add(e,set=new HashSet<long>());Index(e);}set.Add(id);if(set.Count>2)throw new ArgumentException("Nonmanifold upstreamCDT domain");}}
   void Remove(long id){var t=faces[id];faces.Remove(id);density.Remove(id);foreach(var e in Edges(t)){adj[e].Remove(id);if(adj[e].Count==0)adj.Remove(e);}}
   // Explicit protectedband avoids forcing farseams fine via trianglecircumradius.
   // Offset2.01m with1mm arc tolerance conservatively contains requested2m band.
   var band=ManagedTerrainDensityBand.Build(sourceUnion,x0,z0,l.InputVertices);if(band.Sum(p=>p.Count)>l.InputVertices)throw new TerrainBudgetException("Protectedband contourcap");
   var xa=xs.ToArray();var za=zs.ToArray();for(int zi=0;zi<za.Length-1;zi++)for(int xi=0;xi<xa.Length-1;xi++){
    token.ThrowIfCancellationRequested();var rect=new Paths64{new Path64{new Point64(xa[xi],za[zi]),new Point64(xa[xi+1],za[zi]),new Point64(xa[xi+1],za[zi+1]),new Point64(xa[xi],za[zi+1])}};var terrain=Clipper.Difference(rect,sourceUnion,FillRule.NonZero);
    for(byte region=1;region<=2;region++){var target=region==1?Clipper.Intersect(terrain,band,FillRule.NonZero):Clipper.Difference(terrain,band,FillRule.NonZero);targetContours.AddRange(target);int count=target.Sum(p=>p.Count);maxCall=Math.Max(maxCall,count);if(count>l.InputVertices)throw new TerrainBudgetException("Booleanoutput/CDTinput cap");foreach(var path in target)foreach(var p in path)protectedPoints.Add(new P(p.X,p.Y));if(count==0)continue;var status=Clipper.Triangulate(target,out var tri,true);calls++;if(status!=TriangulateResult.success)throw new ArgumentException("BoundedCDT failed "+status);if(tri.Count+faces.Count>l.InitialTriangles)throw new TerrainBudgetException("InitialCDT outputcap");foreach(var t in tri){if(t.Count!=3)throw new ArgumentException("NontriangleCDT output");Add(Vertex(new P(t[0].X,t[0].Y)),Vertex(new P(t[1].X,t[1].Y)),Vertex(new P(t[2].X,t[2].Y)),region);}}
   }
   var hardKeysRemaining=new HashSet<(float,float)>(hardByFloat.Keys);var existingFloatKeys=new HashSet<(float,float)>(points.Select(p=>((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale))));foreach(var key in hardByFloat.Keys)if(!existingFloatKeys.Contains(key))protectedPoints.Add(new P(Q(originX+key.Item1),Q(originZ+key.Item2)));var sourceSet=new HashSet<P>();foreach(var v in sourceHeightKnots){var p=new P(Q(v.X),Q(v.Z));if(p.X>=x0&&p.X<=x1&&p.Z>=z0&&p.Z<=z1){protectedPoints.Add(p);sourceSet.Add(p);}}if(protectedPoints.Count>l.ProtectedKnots)throw new TerrainBudgetException("Protectedsource/seam knot cap");
   // Bind canonical finalfloat seam/hard points to their existing EXACTinteger
   // contourknot before restoration. Quantizedfloatpoint may lie just outside
   // its prequantized integerinterval; never insert it as a secondnearby knot.
   var contourByFloat=new Dictionary<(float,float),P>();foreach(var path in targetContours)foreach(var q in path){var p=new P(q.X,q.Y);var key=((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale));if(contourByFloat.TryGetValue(key,out var old)&&!old.Equals(p))throw new TerrainRefinementFailure("integer-localfloat-collapse","Distinct integercontour knots collapse at actualbinary32; explicit union-preserving repair required",new{origin=new[]{originX,originZ},integerA=new[]{old.X,old.Z},integerB=new[]{p.X,p.Z},localFloat=new[]{key.Item1,key.Item2},separation=Math.Sqrt(Math.Pow((double)(p.X-old.X)/Scale,2)+Math.Pow((double)(p.Z-old.Z)/Scale,2)),aOnSourceBoundary=sourceUnion.Any(r=>Enumerable.Range(0,r.Count).Any(i=>Cross(new P(r[i].X,r[i].Y),new P(r[(i+1)%r.Count].X,r[(i+1)%r.Count].Y),old).IsZero)),aHard=hardByFloat.ContainsKey(key),aSeam=seamPoints.ContainsKey(key)});contourByFloat[key]=p;}
   P Canonical(P p){var key=((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale));return contourByFloat.TryGetValue(key,out var original)?original:p;}
   protectedPoints=new HashSet<P>(protectedPoints.Select(Canonical));sourceSet=new HashSet<P>(sourceSet.Select(Canonical));int restored=0,occluded=0;
   foreach(var p in protectedPoints.OrderBy(p=>p.X).ThenBy(p=>p.Z)){Check();if(pointIds.ContainsKey(p))continue;int bx=(int)Math.Floor((double)(p.X-x0)/Scale),bz=(int)Math.Floor((double)(p.Z-z0)/Scale);var candidates=index.TryGetValue((bx,bz),out var indexed)?indexed.Where(e=>adj.ContainsKey(e)).Where(e=>{Check();var a=points[e.A];var b=points[e.B];return Cross(a,b,p).IsZero&&p.X>=Math.Min(a.X,b.X)&&p.X<=Math.Max(a.X,b.X)&&p.Z>=Math.Min(a.Z,b.Z)&&p.Z<=Math.Max(a.Z,b.Z);}).OrderBy(e=>e.A).ThenBy(e=>e.B).ToArray():Array.Empty<TerrainMeshEdge>();if(candidates.Length==0){if(!hardByFloat.ContainsKey(((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale)))&&sourceSet.Contains(p)&&!TargetContains(p)){occluded++;continue;} // Seam inside asphalt is legitimately outside terrain.
     bool seamPoint=seamPoints.ContainsKey(((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale)));if(seamPoint&&!hardByFloat.ContainsKey(((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale)))&&!TargetContains(p))continue;throw new ArgumentException("UpstreamCDT lost mandatory noncollinear domainknot x="+((double)p.X/Scale).ToString("R")+" z="+((double)p.Z/Scale).ToString("R")+" sourceInfluence="+sourceSet.Contains(p)+" hard="+hardByFloat.ContainsKey(((float)((double)(p.X-x0)/Scale),(float)((double)(p.Z-z0)/Scale))));}
    int mid=Vertex(p);foreach(var e in candidates){if(!adj.TryGetValue(e,out var set))continue;foreach(long id in set.OrderBy(i=>i).ToArray()){var t=faces[id];int c=t.A!=e.A&&t.A!=e.B?t.A:t.B!=e.A&&t.B!=e.B?t.B:t.C;byte region=density[id];Remove(id);Add(e.A,mid,c,region);Add(mid,e.B,c,region);}}restored++;
   }
   var sourceBoundaryVertices=new HashSet<int>();foreach(var pair in adj)if(pair.Value.Count==1){var a=points[pair.Key.A];var b=points[pair.Key.B];bool outer=(a.X==b.X&&(a.X==x0||a.X==x1))||(a.Z==b.Z&&(a.Z==z0||a.Z==z1));if(!outer){sourceBoundaryVertices.Add(pair.Key.A);sourceBoundaryVertices.Add(pair.Key.B);}}var output=new TerrainPoint[points.Count];var actualKeys=new HashSet<(float,float)>();for(int i=0;i<points.Count;i++){Check();var p=points[i];float x=(float)((double)(p.X-x0)/Scale),z=(float)((double)(p.Z-z0)/Scale);if(!actualKeys.Add((x,z)))throw new ArgumentException("Booleanquantization collided at actualbinary32; explicit conforming repair required");bool outer=p.X==x0||p.X==x1||p.Z==z0||p.Z==z1;float y;if(outer){if(!seamPoints.TryGetValue((x,z),out y))throw new ArgumentException("Missing canonical source/DEM intersection in sharedseam prepass");}else{var sample=query(originX+x,originZ+z);if(sourceBoundaryVertices.Contains(i)&&sample.Authority!=TerrainHeightAuthority.SourcePavement)throw new ArgumentException("Sourceboundary requires actualpavement triangleplane authority, not coincident analyticfield Y");y=(float)sample.Y;}if(hardByFloat.TryGetValue((x,z),out float sourceY)){if(Math.Abs(y-sourceY)>.0002)throw new ArgumentException("Terrain sourceplane query disagrees with exposedground constraint; cannot flatten sourcebank");if(outer&&y!=sourceY)throw new ArgumentException("Hard sourceY and sharedseam bits disagree; refine canonical BOTHneighbor plan before admission");y=sourceY;hardKeysRemaining.Remove((x,z));}output[i]=new TerrainPoint(x,y,z);}
   if(hardKeysRemaining.Count!=0)throw new ArgumentException("Exposedsource knot missing from conforming terrain boundary; no silentloss");
   var fixedEdges=new Dictionary<TerrainMeshEdge,TerrainConstraintKind>();foreach(var kv in adj){var a=points[kv.Key.A];var b=points[kv.Key.B];TerrainConstraintKind kind=TerrainConstraintKind.None;if(kv.Value.Count==1){bool outer=(a.X==b.X&&(a.X==x0||a.X==x1))||(a.Z==b.Z&&(a.Z==z0||a.Z==z1));kind=outer?TerrainConstraintKind.SharedSeam:TerrainConstraintKind.SourcePlane;}else if((a.X==b.X&&xs.Contains(a.X))||(a.Z==b.Z&&zs.Contains(a.Z)))kind=TerrainConstraintKind.DemCell;if(kv.Value.Count==2&&kv.Value.Select(id=>density[id]).Distinct().Count()==2)kind|=TerrainConstraintKind.DensityBoundary;if(kind!=TerrainConstraintKind.None)fixedEdges[kv.Key]=kind;}
   token.ThrowIfCancellationRequested();return new LocalTerrainDomainInput{OriginX=originX,OriginY=0,OriginZ=originZ,Vertices=output,Density=faces.OrderBy(p=>p.Key).Select(p=>density[p.Key]).ToArray(),Triangles=faces.OrderBy(p=>p.Key).SelectMany(p=>new[]{p.Value.A,p.Value.B,p.Value.C}).ToArray(),Constraints=fixedEdges,BooleanCalls=calls,MaximumCallVertices=maxCall,RestoredKnots=restored,OccludedInfluenceKnots=occluded,Work=work};
  }
